  function lang(){ const value=(document.documentElement.lang||'en').toLowerCase(); return value.startsWith('th')?'th':value.startsWith('ja')?'ja':'en'; }
  function c(){ return COPY[lang()]||COPY.en; }
  function t(key,vars={}){ let value=c()[key]??COPY.en[key]??key; Object.entries(vars).forEach(([k,v])=>{value=String(value).replaceAll(`{${k}}`,String(v));}); return value; }
  function svg(name){ return `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`; }
  function formatBytes(value){ const bytes=n(value); if(bytes===0)return '0 B'; const units=['B','KB','MB','GB','TB']; let i=Math.min(units.length-1,Math.floor(Math.log(bytes)/Math.log(1024))); if(!Number.isFinite(i)||i<0)i=0; const num=bytes/Math.pow(1024,i); return `${num>=100||i===0?Math.round(num):num>=10?num.toFixed(1):num.toFixed(2)} ${units[i]}`; }
  function formatCount(value){ try{return new Intl.NumberFormat(lang()==='th'?'th-TH':lang()==='ja'?'ja-JP':'en-US',{maximumFractionDigits:0}).format(n(value));}catch(_){return String(Math.round(n(value)));} }
  function formatDate(value){ const ms=n(value); if(!ms)return t('dateUnknown'); try{return new Intl.DateTimeFormat(lang()==='th'?'th-TH':lang()==='ja'?'ja-JP':'en-US',{year:'numeric',month:'short',day:'numeric'}).format(new Date(ms));}catch(_){return t('dateUnknown');} }
  function ageText(ms){ const age=Math.max(0,Date.now()-n(ms)); const min=Math.floor(age/60000); return min<1?t('current'):`${formatCount(min)} ${t('minAgo')}`; }
